INSERT INTO `dimensions` VALUES (1,'ekonomi-budaya','Ekonomi Budaya','D1','ekonomibudaya.png','Aktivitas ekonomi yang tercipta sebagai hasil dari pemanfaatan Objek Pemajuan Kebudayaan',NULL,NULL),(2,'pendidikan','Pendidikan','D2','pendidikan.png','Usaha sadar dan terencana untuk mewujudkan suasana belajar dan proses pembelajaran yang inklusif agar peserta didik secara aktif mengembangkan potensi dirinya dalam bidang Seni, Budaya, dan Bahasa',NULL,NULL),(3,'ketahanan-sosial-budaya','Ketahanan Sosial Budaya','D3','ketahanannasional.png','Ketahanan Sosial Budaya Ketahanan Sosial Budaya dalam konteks penyusunan IPK didefinisikan sebagai kemampuan suatu kebudayaan dalam mempertahankan dan mengembangkan identitas, pengetahuan, serta praktik budayanya yang relevan yang didukung oleh kondisi sosial dalam masyarakat.',NULL,NULL),(4,'warisan-budaya','Warisan Budaya','D4','warisanbudaya.png','Upaya yang dilakukan seluruh pihak (masyarakat dan pemerintah) terhadap pelestarian Objek Pemajuan Kebudayaan dan Cagar Budaya',NULL,NULL),(5,'ekspresi-budaya','Ekspresi Budaya','D5','kebebasanbudaya.png','Segala aktivitas yang dilakukan untuk mendukung proses penciptaan karya budaya yang dihasilkan masyarakat',NULL,NULL),(6,'budaya-literasi','Budaya Literasi','D6','literasibudaya.png','Aktivitas serta sarana/prasarana pendukung dalam memperoleh, menguji kesahihan, dan menghasilkan informasi dan pengetahuan untuk pemberdayaan kecakapan masyarakat',NULL,NULL),(7,'gender','Gender','D7','gender.png','Persamaan hak, tanggung jawab dan peluang yang setara antara perempuan dan laki-laki di ruang publik untuk berpartisipasi dalam kegiatan pembangunan',NULL,NULL);
/*!40000 ALTER TABLE `dimensions` ENABLE KEYS */;
UNLOCK TABLES;

