INSERT INTO `indicators` VALUES (1,1,'X1.1','Persentase penduduk 15 tahun ke atas yang pernah terlibat sebagai pelaku/pendukung pertunjukan seni yang menjadikan keterlibatannya itu sebagai sumber penghasilan','Susenas MSBP',0.00,1.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(2,2,'X2.1','Rata-rata Lama Sekolah (MYS) penduduk usia 25 tahun ke atas','Susenas KOR',0.00,15.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(3,2,'X2.2','Harapan Lama Sekolah (HLS) penduduk usia 7 tahun ke atas','Susenas KOR',0.00,18.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(4,2,'X2.3','Angka Kesiapan Sekolah (AKS)','Susenas KOR',0.00,100.00,'2024-08-19 13:22:47','2024-08-19 13:22:47'),(5,2,'X2.4','Persentase satuan pendidikan yang mempunyai guru yang mengajar muatan lokal bahasa daerah dan/atau ekskul kesenian','Kemendikbud (DAPODIK)',0.00,45.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(6,2,'X2.5','Persentase penduduk penyandang disabilitas usia 7-18 tahun yang bersekolah','Susenas KOR',0.00,100.00,'2024-08-19 13:22:47','2024-08-19 13:22:47'),(7,2,'X2.6','Persentase penduduk usia 7-18 tahun dengan kategori kelompok pengeluaran 40 persen terbawah yang bersekolah','Susenas KOR',0.00,100.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(8,3,'X3.1','Persentase rumah tangga yang setuju jika ada sekelompok orang dari agama lain yang melakukan kegiatan di lingkungan sekitar tempat tinggal.','Susenas MSBP',0.00,100.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(9,3,'X3.2','Persentase rumah tangga yang setuju jika ada sekelompok orang dari suku lain yang melakukan kegiatan di lingkungan sekitar tempat tinggal.','Susenas MSBP',0.00,100.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(10,3,'X3.3','Persentase rumah tangga yang setuju jika salah satu anggota rumah tangga berteman dengan orang lain yang beda agama.','Susenas MSBP',0.00,100.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(11,3,'X3.4','Persentase rumah tangga yang setuju jika salah satu anggota rumah tangga berteman dengan orang lain yang berbeda suku.','Susenas MSBP',0.00,100.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(12,3,'X3.5','Persentase penduduk usia 10 tahun ke atas yang mengikuti kegiatan sosial kemasyarakatan di lingkungan sekitar dalam 3 bulan terakhir','Susenas MSBP',0.00,100.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(13,3,'X3.6','Persentase penduduk usia 10 tahun ke atas yang mengikuti gotong royong','Susenas MSBP',0.00,100.00,'2024-08-19 13:22:47','2024-08-19 13:22:47'),(14,3,'X3.7','Persentase rumah tangga yang merasa khawatir dengan keamanan saat berjalan kaki sendirian di malam hari','Susenas Hansos/SPTK',0.00,50.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(15,3,'X3.8','Persentase rumah tangga yang merasa percaya menitipkan rumah kepada tetangga','Susenas Hansos/SPTK',0.00,100.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(16,4,'X4.1','Persentase benda, bangunan, struktur, situs dan kawasan cagar budaya yang telah ditetapkan terhadap total pendaftaran','Kemendikbud (DAPOBUD)',0.00,50.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(17,4,'X4.2','Persentase warisan budaya takbenda yang telah ditetapkan terhadap total pencatatan','Kemendikbud (DAPOBUD)',0.00,50.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(18,4,'X4.3','Persentase penduduk usia 5 tahun ke atas yang menggunakan bahasa daerah di rumah atau dalam pergaulan sehari-hari','Susenas MSBP',0.00,100.00,'2024-08-19 13:22:47','2024-08-19 13:22:59'),(19,4,'X4.4','Persentase penduduk usia 10 tahun ke atas yang menonton secara langsung pertunjukkan seni dalam 3 bulan terakhir.<br>*tahun 2021 ada perluasan definisi operasional (termasuk yang tidak langsung) dari nilai maksimum 70 untuk tahun 2018-2020 menjadi nilai maksimum 100 untuk tahun 2021-2022','Susenas MSBP',0.00,100.00,'2024-08-19 13:22:47','2024-08-19 13:23:02'),(20,4,'X4.5','Persentase penduduk usia 10 tahun ke atas yang mengunjungi peninggalan sejarah/warisan dunia dalam setahun terakhir','Susenas MSBP',0.00,30.00,'2024-08-19 13:22:47','2024-